import{D as r,o as a,c as t,m as i}from"./chunks/framework.wL2BuMsi.js";const f=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"editLinkUrl":"https://github.com/signalityjs/signality/blob/main/CHANGELOG.md"},"headers":[],"relativePath":"resources/changelog.md","filePath":"resources/changelog.md","lastUpdated":0}'),l={name:"resources/changelog.md"};function o(s,e,n,c,h,g){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-5-0-2026-08-23" tabindex="-1">0.5.0 (2026-08-23) <a class="header-anchor" href="#_0-5-0-2026-08-23" aria-label="Permalink to “0.5.0 (2026-08-23)”">​</a></h2><h3 id="🚀-features" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/battery"><code>battery</code></a> add injection token for singleton usage (<a href="https://github.com/signalityjs/signality/pull/206" target="_blank" rel="noreferrer">#206</a>)</li><li><strong>core:</strong> <a href="/browser/device-posture"><code>devicePosture</code></a> add injection token for singleton usage (<a href="https://github.com/signalityjs/signality/pull/208" target="_blank" rel="noreferrer">#208</a>)</li><li><strong>core:</strong> <a href="/browser/gamepad"><code>gamepad</code></a> add injection token for singleton usage (<a href="https://github.com/signalityjs/signality/pull/210" target="_blank" rel="noreferrer">#210</a>)</li><li><strong>core:</strong> <a href="/elements/on-key"><code>onKey</code></a> now supports chainable modifiers (<a href="https://github.com/signalityjs/signality/pull/213" target="_blank" rel="noreferrer">#213</a>)</li><li><strong>core:</strong> <a href="/scheduling/throttle-callback"><code>throttleCallback</code></a> add <code>leading</code> and <code>trailing</code> options (<a href="https://github.com/signalityjs/signality/pull/217" target="_blank" rel="noreferrer">#217</a>)</li><li><strong>core:</strong> <a href="/reactivity/throttled"><code>throttled</code></a> add <code>leading</code> and <code>trailing</code> options (<a href="https://github.com/signalityjs/signality/pull/219" target="_blank" rel="noreferrer">#219</a>)</li><li><strong>core:</strong> <a href="/browser/broadcast-channel"><code>broadcastChannel</code></a> now supports signal options for the <code>data</code> signal (<a href="https://github.com/signalityjs/signality/pull/225" target="_blank" rel="noreferrer">#225</a>)</li><li>⚠️ <strong>core:</strong> <a href="/browser/window-size"><code>windowSize</code></a> expose <code>width</code> and <code>height</code> as separate signals (<a href="https://github.com/signalityjs/signality/pull/243" target="_blank" rel="noreferrer">#243</a>)</li></ul><h3 id="🩹-fixes" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/listener"><code>listener</code></a> preserve modifier chain when a modifier is repeated (<a href="https://github.com/signalityjs/signality/pull/215" target="_blank" rel="noreferrer">#215</a>)</li><li><strong>core:</strong> <a href="/browser/permission-state"><code>permissionState</code></a> correctly sync initial state from the resolved query (<a href="https://github.com/signalityjs/signality/pull/221" target="_blank" rel="noreferrer">#221</a>)</li><li><strong>core:</strong> <a href="/observers/resize-observer"><code>resizeObserver</code></a> prevent observation from resuming after <code>destroy()</code> (<a href="https://github.com/signalityjs/signality/pull/223" target="_blank" rel="noreferrer">#223</a>)</li><li><strong>core:</strong> <a href="/browser/fullscreen"><code>fullscreen</code></a> correctly sync initial state from the DOM (<a href="https://github.com/signalityjs/signality/pull/227" target="_blank" rel="noreferrer">#227</a>)</li><li><strong>core:</strong> <a href="/elements/on-click-outside"><code>onClickOutside</code></a> ignore clicks while the target is absent (<a href="https://github.com/signalityjs/signality/pull/230" target="_blank" rel="noreferrer">#230</a>)</li><li><strong>core:</strong> <a href="/elements/active-element"><code>activeElement</code></a> cancel the deferred shadow focusout sync on destroy (<a href="https://github.com/signalityjs/signality/pull/232" target="_blank" rel="noreferrer">#232</a>)</li><li><strong>core:</strong> <a href="/browser/battery"><code>battery</code></a> handle a rejected <code>getBattery()</code> query (<a href="https://github.com/signalityjs/signality/pull/234" target="_blank" rel="noreferrer">#234</a>)</li><li><strong>core:</strong> <a href="/elements/scroll-position"><code>scrollPosition</code></a> measure after the target is rendered (<a href="https://github.com/signalityjs/signality/pull/236" target="_blank" rel="noreferrer">#236</a>)</li><li><strong>core:</strong> <a href="/browser/favicon"><code>favicon</code></a> include every icon link in favicon updates (<a href="https://github.com/signalityjs/signality/pull/238" target="_blank" rel="noreferrer">#238</a>)</li><li><strong>core:</strong> <a href="/browser/fps"><code>fps</code></a> clamp <code>sampleSize</code> to at least one frame (<a href="https://github.com/signalityjs/signality/pull/240" target="_blank" rel="noreferrer">#240</a>)</li></ul><h3 id="⚠️-breaking-changes" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes" aria-label="Permalink to “⚠️  Breaking Changes”">​</a></h3><ul><li>⚠️ <strong>core:</strong> <a href="/browser/window-size"><code>windowSize</code></a> expose <code>width</code> and <code>height</code> as separate signals (<a href="https://github.com/signalityjs/signality/pull/243" target="_blank" rel="noreferrer">#243</a>)</li></ul><h2 id="_0-4-0-2026-08-04" tabindex="-1">0.4.0 (2026-08-04) <a class="header-anchor" href="#_0-4-0-2026-08-04" aria-label="Permalink to “0.4.0 (2026-08-04)”">​</a></h2><h3 id="🚀-features-1" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-1" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/elements/on-key"><code>onKey</code></a> add new utility for declarative keyboard event handling (<a href="https://github.com/signalityjs/signality/pull/201" target="_blank" rel="noreferrer">#201</a>)</li><li><strong>core:</strong> <a href="/router/query-params"><code>queryParams</code></a> is now a WritableSignal (<a href="https://github.com/signalityjs/signality/pull/202" target="_blank" rel="noreferrer">#202</a>)</li></ul><h2 id="_0-3-3-2026-07-07" tabindex="-1">0.3.3 (2026-07-07) <a class="header-anchor" href="#_0-3-3-2026-07-07" aria-label="Permalink to “0.3.3 (2026-07-07)”">​</a></h2><h3 id="🚀-features-2" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-2" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/listener"><code>listener</code></a> add BroadcastChannelEventMap overload (<a href="https://github.com/signalityjs/signality/pull/195" target="_blank" rel="noreferrer">#195</a>)</li></ul><h3 id="🩹-fixes-1" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-1" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/storage"><code>storage</code></a> use CustomEvent for same-document sync (<a href="https://github.com/signalityjs/signality/pull/198" target="_blank" rel="noreferrer">#198</a>)</li></ul><h2 id="_0-3-2-2026-05-23" tabindex="-1">0.3.2 (2026-05-23) <a class="header-anchor" href="#_0-3-2-2026-05-23" aria-label="Permalink to “0.3.2 (2026-05-23)”">​</a></h2><h3 id="🩹-fixes-2" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-2" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/battery"><code>battery</code></a> prevent error when host is destroyed during initialization (<a href="https://github.com/signalityjs/signality/pull/188" target="_blank" rel="noreferrer">#188</a>)</li><li><strong>core:</strong> <a href="/browser/bluetooth"><code>bluetooth</code></a> prevent error when host is destroyed during request (<a href="https://github.com/signalityjs/signality/pull/190" target="_blank" rel="noreferrer">#190</a>)</li><li><strong>core:</strong> <a href="/browser/display-media"><code>displayMedia</code></a> prevent stream leak when host is destroyed during start (<a href="https://github.com/signalityjs/signality/pull/192" target="_blank" rel="noreferrer">#192</a>)</li></ul><h2 id="_0-3-1-2026-05-09" tabindex="-1">0.3.1 (2026-05-09) <a class="header-anchor" href="#_0-3-1-2026-05-09" aria-label="Permalink to “0.3.1 (2026-05-09)”">​</a></h2><h3 id="🩹-fixes-3" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-3" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/utilities/create-injectable"><code>createInjectable</code></a> export utility types to support declaration file generation (<a href="https://github.com/signalityjs/signality/pull/171" target="_blank" rel="noreferrer">#171</a>)</li><li><strong>core:</strong> <a href="/elements/element-focus"><code>elementFocus</code></a> add assertion for null/undefined reactive target on signal set/update (<a href="https://github.com/signalityjs/signality/pull/177" target="_blank" rel="noreferrer">#177</a>)</li><li><strong>core:</strong> <a href="/browser/text-direction"><code>textDirection</code></a> add assertion for null/undefined reactive target on signal set/update (<a href="https://github.com/signalityjs/signality/pull/179" target="_blank" rel="noreferrer">#179</a>)</li><li><strong>core:</strong> <a href="/router/fragment"><code>fragment</code></a> correctly apply signal options (e.g. debugName) (<a href="https://github.com/signalityjs/signality/pull/181" target="_blank" rel="noreferrer">#181</a>)</li><li><strong>core:</strong> <a href="/reactivity/proxy-signal"><code>proxySignal</code></a> prevent value corruption in update without set handler (<a href="https://github.com/signalityjs/signality/pull/183" target="_blank" rel="noreferrer">#183</a>)</li></ul><h2 id="_0-3-0-2026-04-27" tabindex="-1">0.3.0 (2026-04-27) <a class="header-anchor" href="#_0-3-0-2026-04-27" aria-label="Permalink to “0.3.0 (2026-04-27)”">​</a></h2><h3 id="🚀-features-3" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-3" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/utilities/create-injectable"><code>createInjectable</code></a> add new utility (<a href="https://github.com/signalityjs/signality/pull/152" target="_blank" rel="noreferrer">#152</a>)</li><li><strong>core:</strong> <a href="/router/fragment"><code>fragment</code></a> is now a WritableSignal (<a href="https://github.com/signalityjs/signality/pull/160" target="_blank" rel="noreferrer">#160</a>)</li><li><strong>core:</strong> <a href="/reactivity/proxy-signal"><code>proxySignal</code></a> add new utility (<a href="https://github.com/signalityjs/signality/pull/166" target="_blank" rel="noreferrer">#166</a>)</li></ul><h3 id="🩹-fixes-4" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-4" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/text-direction"><code>textDirection</code></a> correctly sync initial state from the DOM for reactive targets (<a href="https://github.com/signalityjs/signality/pull/167" target="_blank" rel="noreferrer">#167</a>)</li></ul><h2 id="_0-2-0-2026-04-11" tabindex="-1">0.2.0 (2026-04-11) <a class="header-anchor" href="#_0-2-0-2026-04-11" aria-label="Permalink to “0.2.0 (2026-04-11)”">​</a></h2><h3 id="🚀-features-4" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-4" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/listener"><code>listener</code></a> add MediaQueryListEvent overload (<a href="https://github.com/signalityjs/signality/pull/124" target="_blank" rel="noreferrer">#124</a>)</li><li>⚠️ <strong>core:</strong> change utilities error handling to propagate errors by default (<a href="https://github.com/signalityjs/signality/pull/126" target="_blank" rel="noreferrer">#126</a>)</li><li><strong>core:</strong> <a href="/forms/cva"><code>cva</code></a> replace generic CvaOptions type with explicit interface for better readability (<a href="https://github.com/signalityjs/signality/pull/128" target="_blank" rel="noreferrer">#128</a>)</li><li>⚠️ <strong>core:</strong> <a href="/browser/web-notification"><code>webNotification</code></a> simplify api by removing return values (<a href="https://github.com/signalityjs/signality/pull/137" target="_blank" rel="noreferrer">#137</a>)</li><li><strong>core:</strong> <a href="/browser/device-pixel-ratio"><code>devicePixelRatio</code></a> add new utility (<a href="https://github.com/signalityjs/signality/pull/141" target="_blank" rel="noreferrer">#141</a>)</li></ul><h3 id="🩹-fixes-5" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-5" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/forms/cva"><code>cva</code></a> prevent errors when required signal accessed (<a href="https://github.com/signalityjs/signality/pull/130" target="_blank" rel="noreferrer">#130</a>)</li><li><strong>core:</strong> <a href="/browser/web-notification"><code>webNotification</code></a> sync permission with browser permission changes (<a href="https://github.com/signalityjs/signality/pull/139" target="_blank" rel="noreferrer">#139</a>)</li></ul><h2 id="_0-1-3-2026-04-05" tabindex="-1">0.1.3 (2026-04-05) <a class="header-anchor" href="#_0-1-3-2026-04-05" aria-label="Permalink to “0.1.3 (2026-04-05)”">​</a></h2><h3 id="🚀-features-5" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-5" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/utilities/generate-id"><code>generateId</code></a> add new utility for creating unique IDs (<a href="https://github.com/signalityjs/signality/pull/108" target="_blank" rel="noreferrer">#108</a>)</li><li><strong>core:</strong> <a href="/browser/text-selection"><code>textSelection</code></a> add root option to track selections only within a specific element (<a href="https://github.com/signalityjs/signality/pull/110" target="_blank" rel="noreferrer">#110</a>)</li></ul><h3 id="🩹-fixes-6" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-6" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/browser/storage"><code>storage</code></a> dispatch storage event to sync signals with same key in same session (<a href="https://github.com/signalityjs/signality/pull/115" target="_blank" rel="noreferrer">#115</a>)</li></ul><h2 id="_0-1-2-2026-03-28" tabindex="-1">0.1.2 (2026-03-28) <a class="header-anchor" href="#_0-1-2-2026-03-28" aria-label="Permalink to “0.1.2 (2026-03-28)”">​</a></h2><h3 id="🚀-features-6" tabindex="-1">🚀 Features <a class="header-anchor" href="#🚀-features-6" aria-label="Permalink to “🚀 Features”">​</a></h3><ul><li><strong>core:</strong> <a href="/elements/element-focus"><code>elementFocus</code></a> add writable focus control (<a href="https://github.com/signalityjs/signality/pull/100" target="_blank" rel="noreferrer">#100</a>)</li></ul><h3 id="🩹-fixes-7" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-7" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> <a href="/elements/element-visibility"><code>elementVisibility</code></a> properly reset visibility signal on element disconnect (<a href="https://github.com/signalityjs/signality/pull/93" target="_blank" rel="noreferrer">#93</a>)</li><li><strong>core:</strong> <a href="/browser/favicon"><code>favicon</code></a> exclude apple-touch-icon from favicon selection (<a href="https://github.com/signalityjs/signality/pull/95" target="_blank" rel="noreferrer">#95</a>)</li><li><strong>core:</strong> <a href="/elements/element-size"><code>elementSize</code></a> properly reset size signal on element disconnect (<a href="https://github.com/signalityjs/signality/pull/98" target="_blank" rel="noreferrer">#98</a>)</li></ul><h2 id="_0-1-1-2026-03-20" tabindex="-1">0.1.1 (2026-03-20) <a class="header-anchor" href="#_0-1-1-2026-03-20" aria-label="Permalink to “0.1.1 (2026-03-20)”">​</a></h2><h3 id="🩹-fixes-8" tabindex="-1">🩹 Fixes <a class="header-anchor" href="#🩹-fixes-8" aria-label="Permalink to “🩹 Fixes”">​</a></h3><ul><li><strong>core:</strong> ensure bluetooth and speech-recognition types work without <code>skipLibCheck</code> (<a href="https://github.com/signalityjs/signality/pull/72" target="_blank" rel="noreferrer">#72</a>)</li><li><strong>core:</strong> <code>pictureInPicture.enter()</code> assert element and propagate errors to caller (<a href="https://github.com/signalityjs/signality/pull/75" target="_blank" rel="noreferrer">#75</a>)</li></ul><h2 id="_0-1-0-2026-03-20" tabindex="-1">0.1.0 (2026-03-20) <a class="header-anchor" href="#_0-1-0-2026-03-20" aria-label="Permalink to “0.1.0 (2026-03-20)”">​</a></h2><p>This was a version bump only, there were no code changes.</p><h2 id="_0-0-1-alpha-4-2026-03-19" tabindex="-1">0.0.1-alpha.4 (2026-03-19) <a class="header-anchor" href="#_0-0-1-alpha-4-2026-03-19" aria-label="Permalink to “0.0.1-alpha.4 (2026-03-19)”">​</a></h2><p>This was a version bump only, there were no code changes.</p>',49)])])}const u=r(l,[["render",o]]);export{f as __pageData,u as default};
